import sys
input = sys.stdin.readline
from math import gcd
for _ in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	ans = [0] * (n + 1)
	gcds = {}
	sm = 0
	for x in a:
		new_gcds = {x: 1}
		for g in gcds.keys():
			G = gcd(x, g)
			if G not in new_gcds:
				new_gcds[G] = gcds[g] + 1
			else:
				new_gcds[G] = max(new_gcds[G], gcds[g] + 1)
		gcds = new_gcds
		for g in gcds.keys():
			ans[gcds[g]] = max(ans[gcds[g]], g)
	print(*ans[1:])
